{'role': 'user', 'content': [{'tool_use_id': 'toolu_01KwcoQ5yd9xniqStAwR28nQ', 'type': 'tool_result', 'content': '     1→/** Base API client configuration. */
     2→
     3→const BASE_URL = "/api";
     4→
     5→export async function apiFetch<T>(
     6→  path: string,
     7→  init?: RequestInit,
     8→): Promise<T> {
     9→  const res = await fetch(`${BASE_URL}${path}`, {
    10→    ...init,
    11→    headers: {
    12→      "Content-Type": "application/json",
    13→      ...init?.headers,
    14→    },
    15→  });
    16→
    17→  if (!res.ok) {
    18→    const body = await res.text().catch(() => "");
    19→    throw new Error(`API ${res.status}: ${body}`);
    20→  }
    21→
    22→  return res.json() as Promise<T>;
    23→}
    24→'}]}

