{'role': 'user', 'content': [{'tool_use_id': 'toolu_01VZB7SXNCBxUzH6DvzRhnCa', 'type': 'tool_result', 'content': '     1→/** Display formatting helpers. */
     2→
     3→export function formatDuration(seconds: number): string {
     4→  const m = Math.floor(seconds / 60);
     5→  const s = Math.floor(seconds % 60);
     6→  return `${m}:${s.toString().padStart(2, "0")}`;
     7→}
     8→
     9→export function formatBpm(bpm: number): string {
    10→  return bpm > 0 ? bpm.toFixed(1) : "—";
    11→}
    12→
    13→export function formatDate(unixTs: number): string {
    14→  if (!unixTs) return "—";
    15→  return new Date(unixTs * 1000).toLocaleDateString("en-US", {
    16→    month: "short",
    17→    day: "numeric",
    18→    year: "numeric",
    19→  });
    20→}
    21→
    22→export function truncateFingerprint(fp: string, len = 8): string {
    23→  return fp.slice(0, len);
    24→}
    25→'}]}

